INSERT INTO author_texts (author_id, locale, name, bio, meta_description) VALUES ('geshors-yann', 'ka', 'GESHORS Yann', NULL, NULL), ('giga-shushtakashvili', 'ka', 'გიგა შუშტაკაშვილი', NULL, NULL), ('giga-shushtakashvili', 'en', 'Giga Shushtakashvili', NULL, NULL), ('giga-shushtakashvili', 'ru', 'Гига Шуштакашвили', NULL, NULL), ('giga-shushtakashvili', 'tr', 'Giga Shushtakashvili', NULL, NULL), ('giles-laurent', 'ka', 'Giles Laurent', NULL, NULL), ('gilles-san-martin', 'ka', 'Gilles San Martin', NULL, NULL), ('gintautas-steiblys', 'ka', 'Gintautas Steiblys', NULL, NULL), ('gio-modzmana', 'ka', 'გიო მოძმანა', NULL, NULL), ('gio-modzmana', 'en', 'Gio Modzmana', NULL, NULL), ('gio-modzmana', 'ru', 'Гио Модзмана', NULL, NULL), ('gio-modzmana', 'tr', 'Gio Modzmana', NULL, NULL), ('gio-tatulishvili', 'ka', 'გიო ტატულიშვილი', NULL, NULL), ('gio-tatulishvili', 'en', 'Gio Tatulishvili', NULL, NULL), ('gio-tatulishvili', 'ru', 'Гио Татулишвили', NULL, NULL), ('gio-tatulishvili', 'tr', 'Gio Tatulishvili', NULL, NULL), ('giorgi-chaladze', 'ka', 'გიორგი ჩალაძე', NULL, NULL), ('giorgi-chaladze', 'en', 'Giorgi Chaladze', NULL, NULL), ('giorgi-chaladze', 'ru', 'Гиорги Чаладзе', NULL, NULL), ('giorgi-chaladze', 'tr', 'Giorgi Chaladze', NULL, NULL), ('giorgi-iankoshvili', 'ka', 'გიორგი იანქოშვილი', 'გიორგი იანქოშვილი არის ქართველი მკვლევარი-ეკოლოგი და ჰერპეტოლოგი. ამჟამად ილიას სახელმწიფო უნივერსიტეტის ეკოლოგიის ინსტიტუტის მკვლევარია და ამავე უნივერსიტეტის დოქტორანტი.', NULL), ('giorgi-iankoshvili', 'en', 'Giorgi Iankoshvili', 'Giorgi Iankoshvili is a Georgian researcher-ecologist and herpetologist. He is currently a researcher at the Institute of Ecology at Ilia State University and a doctoral student at the same university.', NULL), ('giorgi-iankoshvili', 'ru', 'Гиорги Ианкошвили', 'Гиорги Ианкошвили — грузинский исследователь-эколог и герпетолог. Сейчас он исследователь Института экологии Государственного университета Ильи и докторант того же университета.', NULL), ('giorgi-iankoshvili', 'tr', 'Giorgi Iankoshvili', 'Giorgi Iankoshvili Gürcü araştırmacı-ekolog ve herpetologdur. Şu anda Ilia Devlet Üniversitesi Ekoloji Enstitüsü’nde araştırmacı ve aynı üniversitede doktora öğrencisidir.', NULL), ('giorgi-kikuashvili', 'ka', 'გიორგი კიკუაშვილი', NULL, NULL), ('giorgi-kikuashvili', 'en', 'Giorgi Kikuashvili', NULL, NULL), ('giorgi-kikuashvili', 'ru', 'Гиорги Кикуашвили', NULL, NULL), ('giorgi-kikuashvili', 'tr', 'Giorgi Kikuashvili', NULL, NULL), ('giorgi-makharadze', 'ka', 'გიორგი მახარაძე', NULL, NULL), ('giorgi-makharadze', 'en', 'Giorgi Makharadze', NULL, NULL), ('giorgi-makharadze', 'ru', 'Гиорги Махарадзе', NULL, NULL), ('giorgi-makharadze', 'tr', 'Giorgi Makharadze', NULL, NULL), ('giorgi-nadareishvili', 'ka', 'გიორგი ნადარეიშვილი', NULL, NULL), ('giorgi-nadareishvili', 'en', 'Giorgi Nadareishvili', NULL, NULL), ('giorgi-nadareishvili', 'ru', 'Гиорги Надареишвили', NULL, NULL), ('giorgi-nadareishvili', 'tr', 'Giorgi Nadareishvili', NULL, NULL), ('giorgi-natsvlishvili', 'ka', 'გიორგი ნაცვლიშვილი', 'გიორგი ნაცვლიშვილი — ბუნების გიდი და ფოტოგრაფი, რომელიც საქართველოს ველური ბუნებისა და ბიომრავალფეროვნების შესწავლით არის დაინტერესებული. 2017 წლიდან პროფესიონალურად უძღვება ბუნებაზე ორიენტირებულ ტურებს საქართველოს სხვადასხვა რეგიონში. ფოტოგრაფიის საშუალებით გიორგი წლების განმავლობაში აფიქსირებს საქართველოს ფაუნასა და ბუნებრივ გარემოს. მისი ნამუშევრები გამოქვეყნებულია სამეცნიერო ნაშრომებსა და საქართველოს ველური ბუნების გზამკვლევში. განსაკუთრებით დაინტერესებულია სახეობების კონსერვაციით, ბუნების შესახებ ცნობიერების ამაღლებითა და საქართველოს ბიომრავალფეროვნების უკეთ შესწავლით.', NULL), ('giorgi-natsvlishvili', 'en', 'Giorgi Natsvlishvili', 'Giorgi Natsvlishvili is a nature guide and photographer with a deep interest in Georgia’s wildlife and biodiversity. Since 2017 he has professionally led nature-focused tours across different regions of Georgia. Through photography, Giorgi has spent years documenting Georgia’s fauna and natural environment. His work has appeared in scientific publications and in a field guide to Georgia’s wildlife. He is especially interested in species conservation, raising awareness about nature, and better understanding Georgia’s biodiversity.', NULL), ('giorgi-natsvlishvili', 'ru', 'Гиорги Нацвлишвили', 'Гиорги Нацвлишвили — природный гид и фотограф, интересующийся изучением дикой природы и биоразнообразия Грузии. С 2017 года профессионально проводит природные туры в разных регионах Грузии. С помощью фотографии Гиорги годами фиксирует фауну и природную среду Грузии. Его работы опубликованы в научных трудах и в путеводителе по дикой природе Грузии. Особенно интересуется сохранением видов, повышением осведомлённости о природе и более глубоким изучением биоразнообразия Грузии.', NULL), ('giorgi-natsvlishvili', 'tr', 'Giorgi Natsvlishvili', 'Giorgi Natsvlishvili, Gürcistan’ın yaban hayatı ve biyoçeşitliliğini incelemeye ilgi duyan bir doğa rehberi ve fotoğrafçıdır. 2017’den beri Gürcistan’ın farklı bölgelerinde doğa odaklı turlara profesyonel olarak rehberlik etmektedir. Giorgi, fotoğrafçılık aracılığıyla yıllardır Gürcistan’ın faunasını ve doğal çevresini belgelemektedir. Çalışmaları bilimsel yayınlarda ve Gürcistan yaban hayatı rehberinde yer almıştır. Özellikle tür koruma, doğa farkındalığını artırma ve Gürcistan’ın biyoçeşitliliğini daha iyi tanıma konularıyla ilgilenmektedir.', NULL);
INSERT INTO author_texts (author_id, locale, name, bio, meta_description) VALUES ('giorgi-rajebashvili', 'ka', 'გიორგი რაჯებაშვილი', NULL, NULL), ('giorgi-rajebashvili', 'en', 'Giorgi Rajebashvili', NULL, NULL), ('giorgi-rajebashvili', 'ru', 'Гиорги Раджебашвили', NULL, NULL), ('giorgi-rajebashvili', 'tr', 'Giorgi Rajebashvili', NULL, NULL), ('giorgi-rizhvadze', 'ka', 'გიორგი რიჟვაძე', NULL, NULL), ('giorgi-rizhvadze', 'en', 'Giorgi Rizhvadze', NULL, NULL), ('giorgi-rizhvadze', 'ru', 'Гиорги Рижвадзе', NULL, NULL), ('giorgi-rizhvadze', 'tr', 'Giorgi Rizhvadze', NULL, NULL), ('giorgi-sheklashvili', 'ka', 'გიორგი შეყლაშვილი', 'გიორგი შეყლაშვილი ბიოლოგიის სფეროს ქართველი მკვლევარია — ილიას სახელმწიფო უნივერსიტეტის (ISU) დოქტორანტი და ზოოლოგიის ინსტიტუტის მეცნიერ-თანამშრომელი.', NULL), ('giorgi-sheklashvili', 'en', 'Giorgi Sheklashvili', 'Giorgi Sheklashvili is a Georgian researcher in biology, a doctoral student at Ilia State University (ISU), and a researcher at the Institute of Zoology.', NULL), ('giorgi-sheklashvili', 'ru', 'Гиорги Шеклашвили', 'Гиорги Шеклашвили — грузинский исследователь в области биологии, докторант Государственного университета Ильи (ISU) и научный сотрудник Института зоологии.', NULL), ('giorgi-sheklashvili', 'tr', 'Giorgi Sheklashvili', 'Giorgi Sheklashvili, biyoloji alanında çalışan Gürcü bir araştırmacı, Ilia Devlet Üniversitesi (ISU) doktora öğrencisi ve Zooloji Enstitüsü araştırmacısıdır.', NULL), ('giorgi-sulamanidze', 'ka', 'გიორგი სულამანიძე', NULL, NULL), ('giorgi-sulamanidze', 'en', 'Giorgi Sulamanidze', NULL, NULL), ('giorgi-sulamanidze', 'ru', 'Гиорги Суламанидзе', NULL, NULL), ('giorgi-sulamanidze', 'tr', 'Giorgi Sulamanidze', NULL, NULL), ('gocha-nemsadze', 'ka', 'გოჩა ნემსაძე', NULL, NULL), ('gocha-nemsadze', 'en', 'Gocha Nemsadze', NULL, NULL), ('gocha-nemsadze', 'ru', 'Гоча Немсадзе', NULL, NULL), ('gocha-nemsadze', 'tr', 'Gocha Nemsadze', NULL, NULL), ('gogopopo', 'ka', 'gogopopo', NULL, NULL), ('gorbunova-m-s', 'ka', 'Горбунова М.С.', NULL, NULL), ('gormo', 'ka', 'Gormo', NULL, NULL), ('greenstep-ias', 'ka', 'greenstep_ias', NULL, NULL), ('guram-iremashvili', 'ka', 'გურამ ირემაშვილი', NULL, NULL), ('guram-iremashvili', 'en', 'Guram Iremashvili', NULL, NULL), ('guram-iremashvili', 'ru', 'Гурам Иремашвили', NULL, NULL), ('guram-iremashvili', 'tr', 'Guram Iremashvili', NULL, NULL), ('gzen92', 'ka', 'Gzen92', NULL, NULL), ('hannu-varkki', 'ka', 'Hannu Varkki', NULL, NULL), ('hans-norelius', 'ka', 'Hans Norelius', NULL, NULL), ('hectonichus', 'ka', 'Hectonichus', NULL, NULL), ('herbert-herbinia', 'ka', 'ჰერბერტ ჰერბინია', NULL, NULL), ('herbert-herbinia', 'en', 'Herbert Herbinia', NULL, NULL), ('herbert-herbinia', 'ru', 'Херберт Хербиния', NULL, NULL), ('herbert-herbinia', 'tr', 'Herbert Herbinia', NULL, NULL), ('hildegarda-von-hildegardenburg', 'ka', 'Hildegarda von Hildegardenburg', NULL, NULL), ('hoiman', 'ka', 'Hoiman', NULL, NULL), ('holger-ellgaard', 'ka', 'Holger.Ellgaard', NULL, NULL), ('hossein-nabizadeh', 'ka', 'hossein_nabizadeh', NULL, NULL);
INSERT INTO author_texts (author_id, locale, name, bio, meta_description) VALUES ('huges4981', 'ka', 'Huges4981', NULL, NULL), ('hyrrokin', 'ka', 'hyrrokin', NULL, NULL), ('ilya-ukolov', 'ka', 'Ilya Ukolov', NULL, NULL), ('ilya-zabaluev', 'ka', 'ილია ზაბალუევი', NULL, NULL), ('ilya-zabaluev', 'en', 'Ilya Zabaluev', NULL, NULL), ('ilya-zabaluev', 'ru', 'Илья Забалуев', NULL, NULL), ('ilya-zabaluev', 'tr', 'Ilya Zabaluev', NULL, NULL), ('imran-shah', 'ka', 'Imran Shah', NULL, NULL), ('ina-loots', 'ka', 'Ina Loots', NULL, NULL), ('ioane-rostiashvili', 'ka', 'იოანე როსტიაშვილი', 'იოანე როსტიაშვილი ახალგაზრდა მკვლევარია — ილიას სახელმწიფო უნივერსიტეტის სტუდენტი. საქმიანობს როგორც მოყვარული ჰერპეტოლოგი (ქვეწარმავლების მკვლევარი), ენტომოლოგი და ველური ბუნების ფოტოგრაფი.', NULL), ('ioane-rostiashvili', 'en', 'Ioane Rostiashvili', 'Ioane Rostiashvili is a young researcher and a student at Ilia State University. He works as an amateur herpetologist (studying reptiles), an entomologist, and a wildlife photographer.', NULL), ('ioane-rostiashvili', 'ru', 'Иоане Ростиашвили', 'Иоане Ростиашвили — молодой исследователь, студент Государственного университета Ильи. Занимается любительской герпетологией (изучение пресмыкающихся), энтомологией и фотографией дикой природы.', NULL), ('ioane-rostiashvili', 'tr', 'Ioane Rostiashvili', 'Ioane Rostiashvili genç bir araştırmacıdır — Ilia Devlet Üniversitesi öğrencisi. Amatör herpetolog (sürüngen araştırmacısı), entomolog ve yaban hayatı fotoğrafçısı olarak çalışır.', NULL), ('irakli-dolidze', 'ka', 'ირაკლი დოლიძე', NULL, NULL), ('irakli-dolidze', 'en', 'Irakli Dolidze', NULL, NULL), ('irakli-dolidze', 'ru', 'Иракли Долидзе', NULL, NULL), ('irakli-dolidze', 'tr', 'Irakli Dolidze', NULL, NULL), ('irakli-shavgulidze', 'ka', 'ირაკლი შავგულიძე', NULL, NULL), ('irakli-shavgulidze', 'en', 'Irakli Shavgulidze', NULL, NULL), ('irakli-shavgulidze', 'ru', 'Иракли Шавгулидзе', NULL, NULL), ('irakli-shavgulidze', 'tr', 'Irakli Shavgulidze', NULL, NULL), ('isi', 'ka', 'Isi', NULL, NULL), ('isiwal', 'ka', 'Isiwal', NULL, NULL), ('ivan-botvinkin', 'ka', 'Ivan Botvinkin', NULL, NULL), ('ivan-bukvic', 'ka', 'Ivan Bukvic', NULL, NULL), ('ivan-medenica', 'ka', 'Ivan Medenica', NULL, NULL), ('ivan-vezenkovic', 'ka', 'Ivan Vezenković', NULL, NULL), ('ivane-goliadze', 'ka', 'ივანე გოლიაძე', NULL, NULL), ('ivane-goliadze', 'en', 'Ivane Goliadze', NULL, NULL), ('ivane-goliadze', 'ru', 'Иване Голиадзе', NULL, NULL), ('ivane-goliadze', 'tr', 'Ivane Goliadze', NULL, NULL), ('j-hokkanen', 'ka', 'J Hokkanen', NULL, NULL), ('jac-janssen', 'ka', 'Jac. Janssen', NULL, NULL), ('jack-roney', 'ka', 'Jack Roney', NULL, NULL), ('jakob-fahr', 'ka', 'Jakob Fahr', NULL, NULL), ('jakub-ha-un', 'ka', 'Jakub Hałun', NULL, NULL), ('james-heal', 'ka', 'James Heal', NULL, NULL), ('james-ray', 'ka', 'James Ray', NULL, NULL), ('jan-ebr', 'ka', 'Jan Ebr', NULL, NULL), ('jan-ebr-ivana-ebrova', 'ka', 'Jan Ebr & Ivana Ebrová', NULL, NULL);
INSERT INTO author_texts (author_id, locale, name, bio, meta_description) VALUES ('janne-teivonen', 'ka', 'Janne Teivonen', NULL, NULL), ('jannic-justen', 'ka', 'jannic_justen', NULL, NULL), ('jarek-matusiak', 'ka', 'Jarek Matusiak', NULL, NULL), ('jaros-aw-krogulec', 'ka', 'იაროსლავ კროგულეცი', NULL, NULL), ('jaros-aw-krogulec', 'en', 'Jarosław Krogulec', NULL, NULL), ('jaros-aw-krogulec', 'ru', 'Ярослав Крогулец', NULL, NULL), ('jaros-aw-krogulec', 'tr', 'Jarosław Krogulec', NULL, NULL), ('jasminel13', 'ka', 'jasminel13', NULL, NULL), ('jean-andrieux', 'ka', 'Jean Andrieux', NULL, NULL), ('jean-louis-carlo', 'ka', 'Jean-Louis Carlo', NULL, NULL), ('jens-loose', 'ka', 'Jens Loose', NULL, NULL), ('jerzy-strzelecki', 'ka', 'Jerzy Strzelecki', NULL, NULL), ('jesus-maria-moro-deordal', 'ka', 'Jesús María Moro Deordal', NULL, NULL), ('jevgenijs-slihto', 'ka', 'Jevgenijs Slihto', NULL, NULL), ('jiri-hromadka', 'ka', 'Jiří Hromádka', NULL, NULL), ('joepon', 'ka', 'joepon', NULL, NULL), ('johannes-worona', 'ka', 'Johannes Worona', NULL, NULL), ('jonathan-ben-simon', 'ka', 'Jonathan Ben Simon', NULL, NULL), ('jonathan-cardy', 'ka', 'Jonathan Cardy', NULL, NULL), ('jose-ibanez', 'ka', 'José Ibañez', NULL, NULL), ('jose-manuel-unanue', 'ka', 'Jose Manuel Unanue', NULL, NULL), ('juan-arrago', 'ka', 'Juan Arrago', NULL, NULL), ('juan-lacruz', 'ka', 'Juan Lacruz', NULL, NULL), ('julian-descoubes', 'ka', 'julian_descoubes', NULL, NULL), ('julien', 'ka', 'Julien', NULL, NULL), ('julien-renoult', 'ka', 'Julien Renoult', NULL, NULL), ('k-korlevic', 'ka', 'K. Korlević', NULL, NULL), ('ka-trin', 'ka', 'Ka Trin', NULL, NULL), ('kakhaber-sukhitashvili', 'ka', 'კახაბერ სუხიტაშვილი', 'კახაბერ სუხიტაშვილი არის ქართველი ეკოლოგი, ბოტანიკოსი და გარემოსდამცველი. იგი უკვე 25 წელზე მეტია აქტიურად მოღვაწეობს გარემოსდაცვით სფეროში. ამჟამად ის არის NatureHistorium-ის წარმომადგენელი და ორგანიზაციის „საქართველოს ბუნების მეგობრები“ (Georgian Society of Nature Friends) დირექტორი.', NULL), ('kakhaber-sukhitashvili', 'en', 'Kakhaber Sukhitashvili', 'Kakhaber Sukhitashvili is a Georgian ecologist, botanist, and environmentalist. He has been active in environmental work for more than 25 years. He is currently a representative of NatureHistorium and the director of the Georgian Society of Nature Friends.', NULL), ('kakhaber-sukhitashvili', 'ru', 'Кахабер Сухиташвили', 'Кахабер Сухиташвили — грузинский эколог, ботаник и защитник природы. Он активно работает в природоохранной сфере более 25 лет. В настоящее время он является представителем NatureHistorium и директором Georgian Society of Nature Friends.', NULL), ('kakhaber-sukhitashvili', 'tr', 'Kakhaber Sukhitashvili', 'Kakhaber Sukhitashvili Gürcü bir ekolog, botanikçi ve çevre korumacıdır. 25 yılı aşkın süredir çevre alanında aktif olarak çalışmaktadır. Şu anda NatureHistorium temsilcisi ve Georgian Society of Nature Friends direktörüdür.', NULL), ('kamilya-medeubaeva', 'ka', 'Kamilya Medeubaeva', NULL, NULL), ('katherine', 'ka', 'Katherine', NULL, NULL), ('katja-schulz', 'ka', 'Katja Schulz', NULL, NULL), ('kattttrin', 'ka', 'kattttrin', NULL, NULL), ('ken-billington', 'ka', 'Ken Billington', NULL, NULL), ('kenny-well', 'ka', 'Kenny Well', NULL, NULL), ('ketevan-feikrishvili', 'ka', 'ქეთევან ფეიქრიშვილი', NULL, NULL), ('ketevan-feikrishvili', 'en', 'Ketevan Feikrishvili', NULL, NULL);
INSERT INTO author_texts (author_id, locale, name, bio, meta_description) VALUES ('ketevan-feikrishvili', 'ru', 'Кетеван Пеикришвили', NULL, NULL), ('ketevan-feikrishvili', 'tr', 'Ketevan Feikrishvili', NULL, NULL), ('kim-erlend-vidal', 'ka', 'Kim Erlend Vidal', NULL, NULL), ('kirill-kotov', 'ka', 'კირილ კოტოვი', NULL, NULL), ('kirill-kotov', 'en', 'Kirill Kotov', NULL, NULL), ('kirill-kotov', 'ru', 'Кирилл Котов', NULL, NULL), ('kirill-kotov', 'tr', 'Kirill Kotov', NULL, NULL), ('kjetil-kjernsmo', 'ka', 'Kjetil Kjernsmo', NULL, NULL), ('konrad-mebert', 'ka', 'Konrad Mebert', NULL, NULL), ('korbinian-aldinger', 'ka', 'Korbinian Aldinger', NULL, NULL), ('kristof-zyskowski-yulia-bereshpolova', 'ka', 'Kristof Zyskowski & Yulia Bereshpolova', NULL, NULL), ('krunku', 'ka', 'krunku', NULL, NULL), ('kseniia-marianna-prondzynska', 'ka', 'ქსენია მარიანა პრონძინსკა', NULL, NULL), ('kseniia-marianna-prondzynska', 'en', 'Kseniia Marianna Prondzynska', NULL, NULL), ('kseniia-marianna-prondzynska', 'ru', 'Ксения Марианна Прондзинская', NULL, NULL), ('kseniia-marianna-prondzynska', 'tr', 'Kseniia Marianna Prondzynska', NULL, NULL), ('kudaibergen-amirekul', 'ka', 'Kudaibergen Amirekul', NULL, NULL), ('lagodekhi-protected-areas', 'ka', 'ლაგოდეხის დაცული ტერიტორიები', NULL, NULL), ('lagodekhi-protected-areas', 'en', 'Lagodekhi Protected Areas', NULL, NULL), ('lagodekhi-protected-areas', 'ru', 'Лагодехские охраняемые территории', NULL, NULL), ('lagodekhi-protected-areas', 'tr', 'Lagodekhi Korunan Alanları', NULL, NULL), ('laotriton', 'ka', 'laotriton', NULL, NULL), ('larisa-nekrasova', 'ka', 'Larisa Nekrasova', NULL, NULL), ('lars-edenius', 'ka', 'Lars Edenius', NULL, NULL), ('lasha-gogodze', 'ka', 'ლაშა გოგოძე', 'ლაშა გოგოძე ქართულ-ამერიკული უმაღლესი სკოლის კურსდამთავრებულია. მონაწილეობდა ტუნისში გამართულ iFest საერთაშორისო კონფერენციაზე და ამჟამად სწავლობს აშშ-ში, Connecticut College-ში, ბიოქიმიისა და მოლეკულური ბიოლოგიის მიმართულებით.', NULL), ('lasha-gogodze', 'en', 'Lasha Gogodze', 'Lasha Gogodze is a graduate of the Georgian-American High School who took part in the iFest international conference in Tunisia and currently studies Biochemistry and Molecular Biology at Connecticut College in the United States.', 'Lasha Gogodze is a graduate of the Georgian-American High School who studies Biochemistry and Molecular Biology at Connecticut College in the US.'), ('lasha-gogodze', 'ru', 'Лаша Гогодзе', 'Лаша Гогодзе — выпускник грузино-американской средней школы, участвовал в международной конференции iFest в Тунисе и сейчас изучает биохимию и молекулярную биологию в Connecticut College в США.', 'Лаша Гогодзе — выпускник грузино-американской средней школы, изучает биохимию и молекулярную биологию в Connecticut College в США.'), ('lasha-gogodze', 'tr', 'Lasha Gogodze', 'Lasha Gogodze, Gürcü-Amerikan Lisesi mezunudur; Tunus’taki iFest uluslararası konferansına katılmış ve şu anda ABD’de Connecticut College’da biyokimya ve moleküler biyoloji okumaktadır.', 'Lasha Gogodze, Gürcü-Amerikan Lisesi mezunudur ve ABD’de Connecticut College’da biyokimya ile moleküler biyoloji okumaktadır.'), ('lasha-javakhishvili', 'ka', 'ლაშა ჯავახიშვილი', NULL, NULL), ('lasha-javakhishvili', 'en', 'Lasha Javakhishvili', NULL, NULL), ('lasha-javakhishvili', 'ru', 'Лаша Джавахишвили', NULL, NULL), ('lasha-javakhishvili', 'tr', 'Lasha Javakhishvili', NULL, NULL), ('laura-and-bobby-bok', 'ka', 'Laura and Bobby Bok', NULL, NULL), ('laura-clark', 'ka', 'Laura Clark', NULL, NULL), ('leda-vanzetta', 'ka', 'Leda Vanzetta', NULL, NULL), ('leekelai', 'ka', 'leekelai', NULL, NULL), ('lela-tsiklauri', 'ka', 'ლელა წიკლაური', NULL, NULL), ('lela-tsiklauri', 'en', 'Lela Tsiklauri', NULL, NULL), ('lela-tsiklauri', 'ru', 'Лела Циклаури', NULL, NULL), ('lela-tsiklauri', 'tr', 'Lela Tsiklauri', NULL, NULL);
