INSERT INTO author_texts (author_id, locale, name, bio, meta_description) VALUES ('mirko-galuppi', 'ka', 'Mirko Galuppi', NULL, NULL), ('mirza-khinkiladze', 'ka', 'მირზა ხინკილაძე', NULL, NULL), ('mirza-khinkiladze', 'en', 'Mirza Khinkiladze', NULL, NULL), ('mirza-khinkiladze', 'ru', 'Мирза Хинкиладзе', NULL, NULL), ('mirza-khinkiladze', 'tr', 'Mirza Khinkiladze', NULL, NULL), ('mladen-stankovic', 'ka', 'Mladen Stankovic', NULL, NULL), ('mobinkargarfard', 'ka', 'mobinkargarfard', NULL, NULL), ('mokhovinka', 'ka', 'Моховинка', NULL, NULL), ('molnar-abel-peter', 'ka', 'Molnár Ábel Péter', NULL, NULL), ('monteanimals', 'ka', 'monteanimals', NULL, NULL), ('mourad-harzallah', 'ka', 'Mourad Harzallah', NULL, NULL), ('musicaline', 'ka', 'Musicaline', NULL, NULL), ('mustafa-gokmen', 'ka', 'mustafa gökmen', NULL, NULL), ('nadav-kavalerchik', 'ka', 'Nadav Kavalerchik', NULL, NULL), ('nagy-sandor', 'ka', 'Nagy Sándor', NULL, NULL), ('nasserhalaweh', 'ka', 'NasserHalaweh', NULL, NULL), ('natalia-bulbulashvili', 'ka', 'ნატალია ბულბულაშვილი', NULL, NULL), ('natalia-bulbulashvili', 'en', 'Natalia Bulbulashvili', NULL, NULL), ('natalia-bulbulashvili', 'ru', 'Наталия Булбулашвили', NULL, NULL), ('natalia-bulbulashvili', 'tr', 'Natalia Bulbulashvili', NULL, NULL), ('natalya-beshko', 'ka', 'Наталья Бешко', NULL, NULL), ('nelson-wisnik', 'ka', 'Nelson Wisnik', NULL, NULL), ('netty3979', 'ka', 'Netty3979', NULL, NULL), ('nevit-dilmen', 'ka', 'Nevit Dilmen', NULL, NULL), ('nicolai-kreher', 'ka', 'Nicolai Kreher', NULL, NULL), ('nika-gagloshvili', 'ka', 'ნიკა გაგლოშვილი', NULL, NULL), ('nika-gagloshvili', 'en', 'Nika Gagloshvili', NULL, NULL), ('nika-gagloshvili', 'ru', 'Ника Гаглошвили', NULL, NULL), ('nika-gagloshvili', 'tr', 'Nika Gagloshvili', NULL, NULL), ('nika-kerdikoshvili', 'ka', 'ნიკა კერდიკოშვილი', 'ნიკა კერდიკოშვილი არის ქართველი ზოოლოგი, ველური ბუნების ფოტოგრაფი და გიდი, რომელიც სპეციალიზებულია ბერდვოჩინგსა (ფრინველებზე დაკვირვება) და ეკოტურებზე საქართველოში. მას აქვს ბიოლოგიური განათლება, კარგად იცნობს საქართველოს ყველაზე შორეულ კუთხეებს და აქტიურად თანამშრომლობს სხვადასხვა გარემოსდაცვით და დოკუმენტური ფილმების მწარმოებელ ორგანიზაციებთან.', NULL), ('nika-kerdikoshvili', 'en', 'Nika Kerdikoshvili', 'Nika Kerdikoshvili is a Georgian zoologist, wildlife photographer, and guide specializing in birdwatching and ecotours in Georgia. He has a background in biology, knows Georgia’s most remote corners well, and actively collaborates with various environmental and documentary film production organizations.', NULL), ('nika-kerdikoshvili', 'ru', 'Ника Кердикошвили', 'Ника Кердикошвили — грузинский зоолог, фотограф дикой природы и гид, специализирующийся на бердвотчинге и экотурах в Грузии. У него биологическое образование, он хорошо знает самые отдалённые уголки Грузии и активно сотрудничает с различными природоохранными организациями и производителями документальных фильмов.', NULL), ('nika-kerdikoshvili', 'tr', 'Nika Kerdikoshvili', 'Nika Kerdikoshvili, Gürcistan’da kuş gözlemciliği ve ekoturlar konusunda uzmanlaşmış Gürcü zoolog, yaban hayatı fotoğrafçısı ve rehberdir. Biyoloji eğitimi vardır, Gürcistan’ın en uzak köşelerini iyi tanır ve çeşitli çevre koruma ve belgesel film yapım kuruluşlarıyla aktif olarak çalışır.', NULL), ('nika-melikishvili', 'ka', 'ნიკა მელიქიშვილი', 'ნიკა მელიქიშვილი ბუნების ფოტოგრაფი და აქტიური ბუნების დამცველია, რომლის ნამუშევრები საქართველოს ველურ ბუნებას ასახავს.', NULL), ('nika-melikishvili', 'en', 'Nika Melikishvili', 'Nika Melikishvili is a nature photographer and an active nature conservationist whose work depicts Georgia’s wildlife.', NULL), ('nika-melikishvili', 'ru', 'Ника Меликишвили', 'Ника Меликишвили — фотограф природы и активный защитник природы, чьи работы отражают дикую природу Грузии.', NULL), ('nika-melikishvili', 'tr', 'Nika Melikishvili', 'Nika Melikishvili, çalışmaları Gürcistan’ın yaban hayatını yansıtan bir doğa fotoğrafçısı ve aktif doğa koruyucusudur.', NULL), ('nika-paposhvili', 'ka', 'ნიკა პაპოშვილი', NULL, NULL), ('nika-paposhvili', 'en', 'Nika Paposhvili', NULL, NULL), ('nika-paposhvili', 'ru', 'Ника Папошвили', NULL, NULL);
