INSERT INTO author_texts (author_id, locale, name, bio, meta_description) VALUES ('wouter-beukema', 'ka', 'Wouter Beukema', NULL, NULL), ('wouter-van-der-ham', 'ka', 'Wouter van der Ham', NULL, NULL), ('wowan1978', 'ka', 'Wowan1978', NULL, NULL), ('xoltc11', 'ka', 'xoltc11', NULL, NULL), ('yaman-omran', 'ka', 'Yaman Omran', NULL, NULL), ('yerevantsi', 'ka', 'Yerevantsi', NULL, NULL), ('yerpo', 'ka', 'Yerpo', NULL, NULL), ('yuri-samoylov', 'ka', 'Yuri Samoylov', NULL, NULL), ('yuvalr', 'ka', 'Yuvalr', NULL, NULL), ('zaharozaur', 'ka', 'zaharozaur', NULL, NULL), ('zakro-songulashvili', 'ka', 'ზაქრო სონღულაშვილი', 'ზაქრო სონღულაშვილი არის ქართველი მკვლევარი, ნატურალისტი და ფოტოგრაფი, რომელიც აქტიურად არის დაკავებული საქართველოში ბიომრავალფეროვნების, განსაკუთრებით კი ჰერპეტოფაუნის (ამფიბიებისა და ქვეწარმავლების) და ფეხსახსრიანების შესწავლითა და დოკუმენტირებით.', NULL), ('zakro-songulashvili', 'en', 'Zakro Songulashvili', 'Zakro Songulashvili is a Georgian researcher, naturalist, and photographer who is actively engaged in studying and documenting biodiversity in Georgia, especially herpetofauna (amphibians/reptiles) and arthropods.', 'Zakro Songulashvili is a Georgian researcher, naturalist, and photographer who studies and documents Georgia’s herpetofauna and arthropods.'), ('zakro-songulashvili', 'ru', 'Закро Сонгулашвили', 'Закро Сонгулашвили — грузинский исследователь, натуралист и фотограф, который активно занимается изучением и документированием биоразнообразия Грузии, особенно герпетофауны (амфибии/рептилии) и членистоногих.', 'Закро Сонгулашвили — грузинский исследователь, натуралист и фотограф, изучающий и документирующий герпетофауну и членистоногих Грузии.'), ('zakro-songulashvili', 'tr', 'Zakro Songulashvili', 'Zakro Songulashvili Gürcü araştırmacı, natüralist ve fotoğrafçıdır; Gürcistan’da biyoçeşitliliği, özellikle herpetofaunayı (amfibiler/sürüngenler) ve eklembacaklıları incelemek ve belgelemekle aktif olarak uğraşır.', 'Zakro Songulashvili, Gürcistan’ın herpetofaunasını ve eklembacaklılarını inceleyip belgeleyen Gürcü araştırmacı, natüralist ve fotoğrafçıdır.'), ('zauri-khachidze', 'ka', 'ზაური ხაჩიძე', 'ბორჯომ-ხარაგაულის ეროვნული პარკის რეინჯერი და ველური ბუნების ფოტოგრაფი. იგი წლების განმავლობაში მუშაობდა დაცულ ტერიტორიაზე, სადაც ბუნების დაცვის საქმიანობასთან ერთად საქართველოს ველური ბუნების მრავალფეროვნებასაც აფიქსირებდა.', NULL), ('zauri-khachidze', 'en', 'Zauri Khachidze', 'Ranger at Borjomi-Kharagauli National Park and wildlife photographer. For years he has worked in the protected area, combining nature protection with documenting the diversity of Georgia’s wildlife.', NULL), ('zauri-khachidze', 'ru', 'Заури Хачидзе', 'Рейнджер Боржомско-Харагаульского национального парка и фотограф дикой природы. Годами работал на охраняемой территории, совмещая охрану природы с фиксацией разнообразия дикой природы Грузии.', NULL), ('zauri-khachidze', 'tr', 'Zauri Khachidze', 'Borjomi-Kharagauli Millî Parkı bekçisi ve yaban hayatı fotoğrafçısı. Yıllardır korunan alanda çalışmış; doğa koruma işinin yanında Gürcistan’ın yaban hayatı çeşitliliğini de belgelemiştir.', NULL), ('zdenek-macat', 'ka', 'Zdeněk Mačát', NULL, NULL), ('zerocool-marko', 'ka', 'Zerocool.marko', NULL, NULL), ('zeynel-cebeci', 'ka', 'Zeynel Cebeci', NULL, NULL), ('zinogre', 'ka', 'Zinogre', NULL, NULL), ('zj-adram', 'ka', 'zj_adram', NULL, NULL), ('zoran-gavrilovic', 'ka', 'Zoran Gavrilović', NULL, NULL), ('zsiciarz', 'ka', 'zsiciarz', NULL, NULL), ('zsolt-semperger', 'ka', 'Zsolt Semperger', NULL, NULL), ('zura-javakhishvili', 'ka', 'ზურა ჯავახიშვილი', NULL, NULL), ('zura-javakhishvili', 'en', 'Zura Javakhishvili', NULL, NULL), ('zura-javakhishvili', 'ru', 'Зура Джавахишвили', NULL, NULL), ('zura-javakhishvili', 'tr', 'Zura Javakhishvili', NULL, NULL);
